spec.rawSql:
SELECT COUNT(*) AS total_trips
FROM traffic_weather_events
WHERE $__timeFilter(event_timestamp);

SELECT ROUND(AVG(travel_time_minutes), 2) AS avg_travel_time
FROM traffic_weather_events
WHERE $__timeFilter(event_timestamp);

SELECT ROUND(AVG(average_speed_kmph), 2) AS avg_speed
FROM traffic_weather_events
WHERE $__timeFilter(event_timestamp);
